+    assert.equal(daemonLaunchOwnerPid(process.env, testFilePid), String(testFilePid));
+    assert.equal(cliDaemonServeLaunch("/daemon-user", "worker").env.HARNESS_DAEMON_OWNER_PID, String(testFilePid));
+  });
+});
+
